1	import type { E2eConfig } from "../config.ts";
2	import { adminToken, assertNoMutationErrors, gql } from "../lib/graphql.ts";
3	import { step } from "../lib/progress.ts";
4	import type { Scenario } from "./scenario.ts";
5	
6	/**
7	 * The default scenario plus the order states the order specs start from.
8	 *
9	 * `populatedb` alone cannot serve them: its orders are random (channel, customer, a 10%
10	 * chance of being unconfirmed, fulfilled whenever they happen to be paid) and its catalogue
11	 * promotions hit random products. So this scenario brings its own products at known prices,
12	 * one known customer, one promotion of each kind, and orders a spec can look up by name -
13	 * see `findOrderId`. Everything lives in one channel.
14	 *
15	 * `populatedb`'s own promotions are deleted, so no price here depends on which products
16	 * its random draw picked.
17	 */
18	export const ORDERS_SCENARIO = "orders";
19	
20	/** Marks orders as paid with a transaction - `populatedb`'s default. */
21	export const CHANNEL = { slug: "default-channel", name: "Channel-USD" } as const;
22	
23	export const CUSTOMER = {
24	  email: "e2e.customer@example.com",
25	  firstName: "Ada",
26	  lastName: "Lovelace",
27	};
28	
29	const CUSTOMER_ADDRESS = {
30	  firstName: CUSTOMER.firstName,
31	  lastName: CUSTOMER.lastName,
32	  streetAddress1: "69 W 9th Street",
33	  city: "New York",
34	  postalCode: "10001",
35	  country: "US",
36	  countryArea: "NY",
37	  phone: "+12125771133",
38	};
39	
40	/** Prices in the channel's currency, USD. */
41	export const PRODUCTS = {
42	  /** Discounted by the catalogue promotion. */
43	  tee: { name: "E2E Tee", sku: "e2e-tee", price: 10 },
44	  hoodie: { name: "E2E Hoodie", sku: "e2e-hoodie", price: 50 },
45	} as const;
46	
47	export const PROMOTIONS = {
48	  catalogue: { name: "E2E Tee sale", percent: 20 },
49	  order: { name: "E2E big basket", percent: 10, subtotalAtLeast: 30 },
50	} as const;
51	
52	/**
53	 * Orders, keyed by what a spec needs from them. Each carries its key as `e2e` metadata,
54	 * which is how `findOrderId` finds it - ids differ per build of the dump.
55	 */
56	export const SCENARIO_ORDERS = {
57	  /** One tee, unpaid and unfulfilled. */
58	  unpaid: { paid: false },
59	  /** One tee, paid and fulfilled. */
60	  fulfilled: { paid: true },
61	} as const;
62	
63	export type ScenarioOrder = keyof typeof SCENARIO_ORDERS;
64	
65	type Mutate = <T extends Record<string, unknown>>(
66	  name: string,
67	  query: string,
68	  variables?: Record<string, unknown>,
69	) => Promise<T>;
70	
71	/** One mutation, failing on the payload's `errors` - see `assertNoMutationErrors`. */
72	const mutator =
73	  (config: E2eConfig, token: string): Mutate =>
74	  async (name, query, variables = {}) => {
75	    const data = await gql<Record<string, { errors?: unknown }>>(config, query, variables, token);
76	
77	    assertNoMutationErrors(name, data[name]?.errors);
78	
79	    return data[name] as never;
80	  };
81	
82	const lookUpShop = async (config: E2eConfig, token: string) => {
83	  const data = await gql<{
84	    channel: { id: string };
85	    categories: { edges: { node: { id: string } }[] };
86	    promotions: { edges: { node: { id: string } }[] };
87	    warehouses: {
88	      edges: {
89	        node: {
90	          id: string;
91	          shippingZones: {
92	            edges: { node: { countries: { code: string }[]; channels: { slug: string }[] } }[];
93	          };
94	        };
95	      }[];
96	    };
97	  }>(
98	    config,
99	    `query($channel: String!) {
100	      channel(slug: $channel) { id }
101	      categories(first: 1) { edges { node { id } } }
102	      promotions(first: 100) { edges { node { id } } }
103	      warehouses(first: 100) {
104	        edges { node { id shippingZones(first: 100) { edges { node { countries { code } channels { slug } } } } } }
105	      }
106	    }`,
107	    { channel: CHANNEL.slug },
108	    token,
109	  );
110	
111	  /* Stock is only sellable through a zone that covers the address in the order's channel. */
112	  const warehouse = data.warehouses.edges.find(({ node }) =>
113	    node.shippingZones.edges.some(
114	      ({ node: zone }) =>
115	        zone.countries.some(({ code }) => code === CUSTOMER_ADDRESS.country) &&
116	        zone.channels.some(({ slug }) => slug === CHANNEL.slug),
117	    ),
118	  );
119	
120	  if (!warehouse) {
121	    throw new Error(`no warehouse ships to ${CUSTOMER_ADDRESS.country} in ${CHANNEL.slug}`);
122	  }
123	
124	  return {
125	    channelId: data.channel.id,
126	    categoryId: data.categories.edges[0].node.id,
127	    promotionIds: data.promotions.edges.map(({ node }) => node.id),
128	    warehouseId: warehouse.node.id,
129	  };
130	};
131	
132	type Shop = Awaited<ReturnType<typeof lookUpShop>>;
133	
134	const createProducts = async (mutate: Mutate, shop: Shop) => {
135	  const { productType } = await mutate<{ productType: { id: string } }>(
136	    "productTypeCreate",
137	    `mutation($input: ProductTypeInput!) {
138	      productTypeCreate(input: $input) { productType { id } errors { field code message } }
139	    }`,
140	    {
141	      input: { name: "E2E Simple", kind: "NORMAL", hasVariants: false, isShippingRequired: true },
142	    },
143	  );
144	  const variantIds: Record<keyof typeof PRODUCTS, string> = { tee: "", hoodie: "" };
145	
146	  for (const [key, product] of Object.entries(PRODUCTS) as [
147	    keyof typeof PRODUCTS,
148	    (typeof PRODUCTS)[keyof typeof PRODUCTS],
149	  ][]) {
150	    const created = await mutate<{ product: { id: string } }>(
151	      "productCreate",
152	      `mutation($input: ProductCreateInput!) {
153	        productCreate(input: $input) { product { id } errors { field code message } }
154	      }`,
155	      { input: { name: product.name, productType: productType.id, category: shop.categoryId } },
156	    );
157	    const { productVariant } = await mutate<{ productVariant: { id: string } }>(
158	      "productVariantCreate",
159	      `mutation($input: ProductVariantCreateInput!) {
160	        productVariantCreate(input: $input) { productVariant { id } errors { field code message } }
161	      }`,
162	      {
163	        input: {
164	          product: created.product.id,
165	          sku: product.sku,
166	          attributes: [],
167	          trackInventory: true,
168	          stocks: [{ warehouse: shop.warehouseId, quantity: 1000 }],
169	        },
170	      },
171	    );
172	
173	    await mutate(
174	      "productChannelListingUpdate",
175	      `mutation($id: ID!, $input: ProductChannelListingUpdateInput!) {
176	        productChannelListingUpdate(id: $id, input: $input) { errors { field code message } }
177	      }`,
178	      {
179	        id: created.product.id,
180	        input: {
181	          updateChannels: [
182	            {
183	              channelId: shop.channelId,
184	              isPublished: true,
185	              visibleInListings: true,
186	              isAvailableForPurchase: true,
187	              addVariants: [productVariant.id],
188	            },
189	          ],
190	        },
191	      },
192	    );
193	    await mutate(
194	      "productVariantChannelListingUpdate",
195	      `mutation($id: ID!, $input: [ProductVariantChannelListingAddInput!]!) {
196	        productVariantChannelListingUpdate(id: $id, input: $input) { errors { field code message } }
197	      }`,
198	      {
199	        id: productVariant.id,
200	        input: [{ channelId: shop.channelId, price: product.price }],
201	      },
202	    );
203	
204	    variantIds[key] = productVariant.id;
205	  }
206	
207	  return variantIds;
208	};
209	
210	const createPromotions = async (mutate: Mutate, shop: Shop, teeProductId: string) => {
211	  if (shop.promotionIds.length > 0) {
212	    await mutate(
213	      "promotionBulkDelete",
214	      `mutation($ids: [ID!]!) { promotionBulkDelete(ids: $ids) { errors { field code message } } }`,
215	      { ids: shop.promotionIds },
216	    );
217	  }
218	
219	  const create = (input: Record<string, unknown>) =>
220	    mutate(
221	      "promotionCreate",
222	      `mutation($input: PromotionCreateInput!) {
223	        promotionCreate(input: $input) { errors { field code message } }
224	      }`,
225	      { input },
226	    );
227	
228	  await create({
229	    name: PROMOTIONS.catalogue.name,
230	    type: "CATALOGUE",
231	    rules: [
232	      {
233	        channels: [shop.channelId],
234	        rewardValueType: "PERCENTAGE",
235	        rewardValue: PROMOTIONS.catalogue.percent,
236	        cataloguePredicate: { productPredicate: { ids: [teeProductId] } },
237	      },
238	    ],
239	  });
240	  await create({
241	    name: PROMOTIONS.order.name,
242	    type: "ORDER",
243	    rules: [
244	      {
245	        channels: [shop.channelId],
246	        rewardType: "SUBTOTAL_DISCOUNT",
247	        rewardValueType: "PERCENTAGE",
248	        rewardValue: PROMOTIONS.order.percent,
249	        orderPredicate: {
250	          discountedObjectPredicate: {
251	            baseSubtotalPrice: { range: { gte: PROMOTIONS.order.subtotalAtLeast } },
252	          },
253	        },
254	      },
255	    ],
256	  });
257	};
258	
259	const createOrder = async (
260	  mutate: Mutate,
261	  {
262	    ref,
263	    channelId,
264	    customerId,
265	    variantId,
266	    warehouseId,
267	    paid,
268	  }: {
269	    ref: ScenarioOrder;
270	    channelId: string;
271	    customerId: string;
272	    variantId: string;
273	    warehouseId: string;
274	    paid: boolean;
275	  },
276	) => {
277	  const { order: draft } = await mutate<{
278	    order: { id: string; shippingMethods: { id: string }[] };
279	  }>(
280	    "draftOrderCreate",
281	    `mutation($input: DraftOrderCreateInput!) {
282	      draftOrderCreate(input: $input) {
283	        order { id shippingMethods { id } }
284	        errors { field code message }
285	      }
286	    }`,
287	    {
288	      input: {
289	        channelId,
290	        user: customerId,
291	        lines: [{ variantId, quantity: 1 }],
292	        shippingAddress: CUSTOMER_ADDRESS,
293	        billingAddress: CUSTOMER_ADDRESS,
294	        metadata: [{ key: "e2e", value: ref }],
295	      },
296	    },
297	  );
298	
299	  await mutate(
300	    "draftOrderUpdate",
301	    `mutation($id: ID!, $input: DraftOrderInput!) {
302	      draftOrderUpdate(id: $id, input: $input) { errors { field code message } }
303	    }`,
304	    { id: draft.id, input: { shippingMethod: draft.shippingMethods[0].id } },
305	  );
306	
307	  const { order } = await mutate<{ order: { id: string; lines: { id: string }[] } }>(
308	    "draftOrderComplete",
309	    `mutation($id: ID!) {
310	      draftOrderComplete(id: $id) { order { id lines { id } } errors { field code message } }
311	    }`,
312	    { id: draft.id },
313	  );
314	
315	  if (!paid) {
316	    return;
317	  }
318	
319	  await mutate(
320	    "orderMarkAsPaid",
321	    `mutation($id: ID!) { orderMarkAsPaid(id: $id) { errors { field code message } } }`,
322	    { id: order.id },
323	  );
324	  await mutate(
325	    "orderFulfill",
326	    `mutation($order: ID!, $input: OrderFulfillInput!) {
327	      orderFulfill(order: $order, input: $input) { errors { field code message } }
328	    }`,
329	    {
330	      order: order.id,
331	      input: {
332	        notifyCustomer: false,
333	        lines: order.lines.map(line => ({
334	          orderLineId: line.id,
335	          stocks: [{ warehouse: warehouseId, quantity: 1 }],
336	        })),
337	      },
338	    },
339	  );
340	};
341	
342	export const ordersScenario: Scenario = {
343	  name: ORDERS_SCENARIO,
344	  parent: "default",
345	  build: async (config, getAdminToken) => {
346	    const token = await getAdminToken();
347	    const mutate = mutator(config, token);
348	    const shop = await lookUpShop(config, token);
349	
350	    const variantIds = await step("creating products", () => createProducts(mutate, shop));
351	    const teeProductId = (
352	      await gql<{ productVariant: { product: { id: string } } }>(
353	        config,
354	        `query($id: ID!) { productVariant(id: $id) { product { id } } }`,
355	        { id: variantIds.tee },
356	        token,
357	      )
358	    ).productVariant.product.id;
359	
360	    await step("replacing the promotions", () => createPromotions(mutate, shop, teeProductId));
361	
362	    const { user } = await mutate<{ user: { id: string } }>(
363	      "customerCreate",
364	      `mutation($input: UserCreateInput!) {
365	        customerCreate(input: $input) { user { id } errors { field code message } }
366	      }`,
367	      {
368	        input: {
369	          ...CUSTOMER,
370	          defaultShippingAddress: CUSTOMER_ADDRESS,
371	          defaultBillingAddress: CUSTOMER_ADDRESS,
372	        },
373	      },
374	    );
375	
376	    await step("creating orders", async () => {
377	      for (const [ref, { paid }] of Object.entries(SCENARIO_ORDERS)) {
378	        await createOrder(mutate, {
379	          ref: ref as ScenarioOrder,
380	          channelId: shop.channelId,
381	          customerId: user.id,
382	          variantId: variantIds.tee,
383	          warehouseId: shop.warehouseId,
384	          paid,
385	        });
386	      }
387	    });
388	  },
389	};
390	
391	/**
392	 * The id of one of `SCENARIO_ORDERS` in the restored database. A read, so it is safe at
393	 * test time; ids are not constants because every build of the dump mints new ones.
394	 */
395	export const findOrderId = async (config: E2eConfig, ref: ScenarioOrder): Promise<string> => {
396	  const data = await gql<{ orders: { edges: { node: { id: string } }[] } }>(
397	    config,
398	    `query($ref: String!) {
399	      orders(first: 1, filter: { metadata: [{ key: "e2e", value: $ref }] }) { edges { node { id } } }
400	    }`,
401	    { ref },
402	    await adminToken(config),
403	  );
404	  const [order] = data.orders.edges;
405	
406	  if (!order) {
407	    throw new Error(`the "${ORDERS_SCENARIO}" scenario has no order "${ref}"`);
408	  }
409	
410	  return order.node.id;
411	};
