3	import { InfoIcon, LinkIcon, MessageSquareIcon, Pencil } from "lucide-react";
4	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
5	import { FormattedMessage } from "react-intl";
6	
7	import { DateTime } from "../Date/DateTime";
8	import { TimelineLink } from "./TimelineLink";
9	import styles from "./TimelineNote.module.css";
10	import { TimelineNoteEdit } from "./TimelineNoteEdit";
11	import { TimelineStem } from "./TimelineStem";
12	import { type Actor } from "./types";
13	import { getActorDisplayName, getActorLink, safeStringify } from "./utils";
14	
15	interface TimelineNoteProps {
16	  date: string | React.ReactNode;
17	  message: string | null;
18	  actor?: Actor;
19	  hasPlainDate?: boolean;
20	  id?: string;
21	  relatedId?: string;
22	  onNoteUpdate?: (id: string, message: string) => Promise<unknown>;
23	  onNoteUpdateLoading?: boolean;
24	  eventData?: unknown;
25	  isLastInGroup?: boolean;
26	}
27	
28	export const TimelineNote = ({
29	  date,
30	  message,
31	  hasPlainDate,
32	  actor,
33	  id,
34	  relatedId,
35	  onNoteUpdate,
36	  onNoteUpdateLoading,
37	  eventData,
38	  isLastInGroup,
39	}: TimelineNoteProps) => {
40	  const actorDisplayName = getActorDisplayName(actor);
41	  const actorLink = getActorLink(actor);
42	  const [showEdit, setShowEdit] = useState(false);
43	  const [isHovered, setIsHovered] = useState(false);
44	  const highlightTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
45	
46	  useEffect(() => {
47	    return () => {
48	      if (highlightTimeoutRef.current) {
49	        clearTimeout(highlightTimeoutRef.current);
50	      }
51	    };
52	  }, []);
53	
54	  const dateToRender =
55	    typeof date === "string" ? <DateTime date={date} plain={hasPlainDate} /> : date;
56	
57	  const eventDataString = useMemo(() => {
58	    if (!eventData) return null;
59	
60	    try {
61	      return safeStringify(eventData);
62	    } catch {
63	      return null;
64	    }
65	  }, [eventData]);
66	
67	  const handleScrollToRelatedNote = useCallback(() => {
68	    if (!relatedId) return;
69	
70	    const element = document.getElementById(`timeline-note-${relatedId}`);
71	
72	    if (!element) return;
73	
74	    element.scrollIntoView({ behavior: "smooth", block: "center" });
75	
76	    const card = element.querySelector("[data-note-card]") as HTMLElement;
77	
78	    if (card) {
79	      card.classList.add(styles.noteCardHighlight);
80	
81	      if (highlightTimeoutRef.current) {
82	        clearTimeout(highlightTimeoutRef.current);
83	      }
84	
85	      highlightTimeoutRef.current = setTimeout(() => {
86	        card.classList.remove(styles.noteCardHighlight);
87	      }, 2000); // Match CSS animation duration
88	    }
89	  }, [relatedId]);
90	
91	  return (
92	    <Box
93	      display="flex"
94	      width="100%"
95	      position="relative"
96	      id={id ? `timeline-note-${id}` : undefined}
97	      onMouseEnter={() => setIsHovered(true)}
98	      onMouseLeave={() => setIsHovered(false)}
99	    >
100	      {/* Vertical connecting line - hidden for last item in group */}
101	      {!isLastInGroup ? <TimelineStem top="32px" bottom="-20px" /> : null}
102	
103	      <Box display="flex" gap={2} marginBottom={5} width="100%">
104	        {/* Left icon column - comment bubble icon */}
105	        <Box
106	          width={10}
107	          display="flex"
108	          justifyContent="center"
109	          flexShrink="0"
110	          paddingTop={1}
111	          position="relative"
112	          __zIndex="1"
113	        >
114	          <Box
115	            display="flex"
116	            alignItems="center"
117	            justifyContent="center"
118	            borderRadius="100%"
119	            backgroundColor="default1"
120	            borderColor="default1"
121	            borderStyle="solid"
122	            borderWidth={1}
123	            __width="32px"
124	            __height="32px"
125	          >
126	            <MessageSquareIcon size={16} color={vars.colors.text.default2} />
127	          </Box>
128	        </Box>
129	
130	        {/* Card content */}
131	        <Box
132	          width="100%"
133	          backgroundColor="default1"
134	          borderRadius={4}
135	          borderStyle="solid"
136	          borderWidth={1}
137	          borderColor="default1"
138	          padding={4}
139	          data-note-card
140	          style={{
141	            transition: "border-color 0.3s ease",
142	          }}
143	        >
144	          {/* Header row with name, info icon, date */}
145	          <Box display="flex" alignItems="center" justifyContent="space-between" marginBottom={2}>
146	            <Box display="flex" alignItems="center" gap={2} flexWrap="wrap">
147	              {actorLink ? (
148	                <TimelineLink
149	                  href={actorLink}
150	                  entity={actor?.type === "app" ? "app" : "staff"}
151	                  color="default2"
152	                >
153	                  {actorDisplayName}
154	                </TimelineLink>
155	              ) : (
156	                <Text size={3} fontWeight="medium" color="default2">
157	                  {actorDisplayName}
158	                </Text>
159	              )}
160	              <Text size={2} color="default2" whiteSpace="nowrap">
161	                {relatedId ? (
162	                  <Box
163	                    as="button"
164	                    type="button"
165	                    display="inline-flex"
166	                    alignItems="center"
167	                    gap={1}
168	                    padding={0}
169	                    borderWidth={0}
170	                    __backgroundColor="transparent"
171	                    __cursor="pointer"
172	                    onClick={handleScrollToRelatedNote}
173	                  >
174	                    <FormattedMessage defaultMessage="edited" id="Zx1w1e" />
175	                    <LinkIcon size={12} />
176	                  </Box>
177	                ) : (
178	                  <FormattedMessage defaultMessage="added" id="xJEaxW" />
179	                )}
180	              </Text>
181	            </Box>
182	            <Box display="flex" alignItems="center" gap={2}>
183	              {eventDataString && (
184	                <Tooltip>
185	                  <Tooltip.Trigger>
186	                    <Box
187	                      as="span"
188	                      cursor="pointer"
189	                      display="inline-flex"
190	                      alignItems="center"
191	                      style={{
192	                        opacity: isHovered ? 1 : 0,
193	                        transition: "opacity 0.15s ease-in-out",
194	                      }}
195	                    >
196	                      <InfoIcon size={16} color={vars.colors.text.default2} />
197	                    </Box>
198	                  </Tooltip.Trigger>
199	                  <Tooltip.Content side="bottom">
200	                    <Tooltip.Arrow />
201	                    <Box
202	                      __maxWidth="400px"
203	                      __maxHeight="300px"
204	                      overflowY="auto"
205	                      __whiteSpace="pre-wrap"
206	                    >
207	                      <Text size={2} fontFamily="Geist Mono" wordBreak="break-all">
208	                        {eventDataString}
209	                      </Text>
210	                    </Box>
211	                  </Tooltip.Content>
212	                </Tooltip>
213	              )}
214	              <Text size={2} color="default2" whiteSpace="nowrap">
215	                {dateToRender}
216	              </Text>
217	            </Box>
218	          </Box>
219	
220	          {/* Message content */}
221	          {showEdit && id ? (
222	            <TimelineNoteEdit
223	              id={id}
224	              note={message!}
225	              onSubmit={onNoteUpdate!}
226	              loading={onNoteUpdateLoading!}
227	              onCancel={() => setShowEdit(false)}
228	            />
229	          ) : (
230	            <Box display="flex" justifyContent="space-between" gap={3} wordBreak="break-all">
231	              <Text style={{ whiteSpace: "pre-wrap" }}>{message}</Text>
232	              {onNoteUpdate && (
233	                <Box
234	                  style={{
235	                    opacity: isHovered ? 1 : 0,
236	                    transition: "opacity 0.15s ease-in-out",
237	                  }}
238	                >
239	                  <Button
240	                    data-test-id="edit-note"
241	                    variant="tertiary"
242	                    size="small"
243	                    onClick={() => setShowEdit(true)}
244	                    icon={
245	                      <Pencil size={iconSize.small} strokeWidth={iconStrokeWidthBySize.small} />
246	                    }
247	                  />
248	                </Box>
249	              )}
250	            </Box>
251	          )}
252	        </Box>
253	      </Box>
254	    </Box>
255	  );
256	};
257	TimelineNote.displayName = "TimelineNote";
