import { e2eConfig } from "../../config.ts";
import { expect, test } from "../../fixtures/test.ts";
import { OrderPage } from "../../pages/orderPage.ts";
import { findOrderId, ORDERS_SCENARIO } from "../../scenarios/orders.ts";

/**
 * Order notes left by a staff member whose only permission is order management
 * (MANAGE_ORDERS): the note appears in the order history and is still there after a reload.
 * This is the first order spec that runs as a non-superuser, so it also proves the session
 * is not the admin's rather than trusting `test.use` alone.
 */
test.use({ scenario: ORDERS_SCENARIO, actor: "order" });

const config = e2eConfig();

test.describe("Order notes as order-permission staff", () => {
  test("Order staff can leave a note that stays in the order history #e2e", async ({ page }) => {
    // Arrange
    const orderPage = new OrderPage(page);
    const note = "Customer called, wants delivery after 5pm";

    await orderPage.goto(await findOrderId(config, "unpaid"));

    // Act & Assert
    await test.step("signed in with only the order permission", async () => {
      // Catalog needs a product or gift-card permission, so a superuser session fails here.
      await expect(orderPage.catalogMenuItem).toBeHidden();
      // Positive control: the sidebar rendered, so the hidden check above is meaningful.
      await expect(orderPage.orderDraftsMenuItem).toBeVisible();
    });

    await test.step("add a note", async () => {
      await orderPage.addNote(note);
      await expect(orderPage.historyNote(note)).toBeVisible();
      await expect(orderPage.noteInput).toHaveValue("");
    });

    await test.step("the note survives a reload", async () => {
      await page.reload();
      await orderPage.statusInfo.waitFor();
      // Only the API can have put the note back after a reload; exactly once rules out a double save.
      await expect(orderPage.historyNote(note)).toHaveCount(1);
      await expect(orderPage.historyNote(note)).toBeVisible();
    });
  });
});

summary:
I've written the spec, but it won't type-check or run until the five `OrderPage` members below are added. I haven't run it, so it is not yet proven against the `orders` scenario or the `order` actor.

I walked the flow by hand in the browser. The seed signs in as admin on default data, so I used populatedb's unpaid order #19. To get its id I looked the order up through GraphQL from the browser. That was only for exploring and none of it is in the spec. What I checked:
- **Note form:** the `Comment` textbox is there and "Add Comment" is disabled while it is empty.
- **Adding:** clicking "Add Comment" shows the "Note added" toast and the note under "Today", and the field is empty again.
- **Reload:** after loading the page again the note is there exactly once.
- **Sidebar:** `menu-item-label-products` and `menu-item-label-order-drafts` each occur once on the page. Catalog is visible for admin, so the "Catalog hidden" check would fail in this session. That is what makes it a useful check, but it is not yet confirmed as hidden for the order actor.

**The spec:** one `test.step` each for "signed in with only the order permission", "add a note" and "the note survives a reload". It follows the setup in the plan and the conventions you listed, and contains no raw locators.

Two choices to review:
- **`test.describe` wrapper:** the generator's rules asked for a `test.describe("Order notes as order-permission staff")` around the test. The model spec has no describe, so remove it if you want them to match.
- **Arrange checks:** I left out the plan's optional check of the empty form and disabled button before adding. The disabled state is the empty-field validation the plan puts out of scope.

**`OrderPage` members the spec uses** (existing: `goto(orderId)`, `statusInfo`; to be added in `/Users/damien/Projects/ai-ready-test-suite-demo/e2e/pages/orderPage.ts`):
```ts
readonly catalogMenuItem = this.page.getByTestId("menu-item-label-products");

