6	/**
7	 * Order notes left by a staff member whose only permission is order management
8	 * (MANAGE_ORDERS): the note appears in the order history and is still there after a reload.
9	 * This is the first order spec that runs as a non-superuser, so it also proves the session
10	 * is not the admin's rather than trusting `test.use` alone.
11	 */
12	test.use({ scenario: ORDERS_SCENARIO, actor: "order" });
