16	test.describe("Order notes as order-permission staff", () => {
17	  test("Order staff can leave a note that stays in the order history #e2e", async ({ page }) => {
18	    // Arrange
19	    const orderPage = new OrderPage(page);
20	    const note = "Customer called, wants delivery after 5pm";
21	
22	    await orderPage.goto(await findOrderId(config, "unpaid"));
23	
24	    // Act & Assert
25	    await test.step("signed in with only the order permission", async () => {
26	      // Catalog needs a product or gift-card permission, so a superuser session fails here.
27	      await expect(orderPage.catalogMenuItem).toBeHidden();
28	      // Positive control: the sidebar rendered, so the hidden check above is meaningful.
29	      await expect(orderPage.orderDraftsMenuItem).toBeVisible();
30	    });
31	
32	    await test.step("add a note", async () => {
33	      await orderPage.addNote(note);
34	      await expect(orderPage.historyNote(note)).toBeVisible();
35	      await expect(orderPage.noteInput).toHaveValue("");
36	    });
37	
38	    await test.step("the note survives a reload", async () => {
39	      await page.reload();
40	      await orderPage.statusInfo.waitFor();
41	      // Only the API can have put the note back after a reload; exactly once rules out a double save.
42	      await expect(orderPage.historyNote(note)).toHaveCount(1);
43	      await expect(orderPage.historyNote(note)).toBeVisible();
44	    });
45	  });
46	});
